import React from 'react';
import { FaHeart, FaTrash } from 'react-icons/fa';
import styles from './BlogCard.module.css';
import PropTypes from 'prop-types';

const BlogCard = ({ title, category, excerpt, image, date, onDelete, id }) => {
  return (
    <div className={styles.blogCard}>
      <div className={styles.imageWrapper}>
        <img src={image} alt={title} className={styles.blogImage} />
        <div className={styles.overlay}></div>
      </div>
      <div className={styles.cardContent}>
        <h3 className={styles.cardTitle}>{title}</h3>
        <p className={styles.categoryLabel}>{category === 'budget' ? 'BUDGET' : `${category.toUpperCase()} FAVES`}</p>
        <p className={styles.date}>{date}</p>
        <FaHeart className={styles.heartIcon} />
        <FaTrash className={styles.deleteIcon} onClick={() => onDelete(id)} />
      </div>
    </div>
  );
};

BlogCard.propTypes = {
  title: PropTypes.string.isRequired,
  category: PropTypes.string.isRequired,
  excerpt: PropTypes.string.isRequired,
  image: PropTypes.string.isRequired,
  date: PropTypes.string.isRequired,
  onDelete: PropTypes.func.isRequired,
  id: PropTypes.string.isRequired,
};

export default BlogCard;
